archetype:
node User {
    has name: str;
    has email: str;
    has created_at: str;
    has is_admin: bool = False;
    has resets: int = 0;
}

node Project {
    has title: str;
    has description: str | None = None;
    has tags: list[str] = [];
}

node Task {
    has title: str;
    has done: bool = False;
    has priority: int | None = None;
}

node Address {
    has street: str;
    has city: str;
    has zip_code: str | None = None;
}

edge Owner: Project --> User {}

edge Tasks: Project --> Task {}

edge TaskProject: Task --> Project {}
